package com.example.inventory

import kotlin.math.max

/** An item in stock. */
data class Item(val name: String, val count: Int = 0)

enum class Level { LOW, HIGH }

interface Repository<T> {
    fun add(item: T)
    fun all(): List<T>
}

class InMemoryRepository : Repository<Item> {
    private val items = mutableListOf<Item>()

    override fun add(item: Item) {
        require(item.count >= 0) { "negative count" }
        items.add(item)
    }

    override fun all(): List<Item> = items.toList()

    val total: Int
        get() = items.sumOf { it.count }
}

fun level(item: Item?): Level {
    val count = item?.count ?: 0
    return when {
        count > 100 -> Level.HIGH
        else -> Level.LOW
    }
}

fun main() {
    val repo = InMemoryRepository()
    for (i in 1..3) {
        repo.add(Item("item$i", i * 10))
    }
    // Print a summary line.
    println("total=${repo.total}, best=${max(repo.total, 1)}")
}

import kotlin.math.abs

fun distance(a: Int, b: Int): Int {
    return abs(a - b)
}

fun main() {
    val values = listOf(3, 8, 1)
    for (v in values) {
        println(distance(v, 5))
    }
}
